{{-- Light / dark / automatic colour mode, handled by resources/js/ui/theme.js --}}
<div class="theme-switch btn-group w-100" role="group" aria-label="Farbmodus">
    <button type="button" class="btn btn-sm btn-outline-secondary" data-theme-value="light" title="Hell"><i class="fa fa-sun"></i><span class="ms-1">Hell</span></button>
    <button type="button" class="btn btn-sm btn-outline-secondary" data-theme-value="dark" title="Dunkel"><i class="fa fa-moon"></i><span class="ms-1">Dunkel</span></button>
    <button type="button" class="btn btn-sm btn-outline-secondary" data-theme-value="auto" title="Wie Gerät"><i class="fa fa-circle-half-stroke"></i><span class="ms-1">Auto</span></button>
</div>
